//! Known answers for the key check as CIRISConstitution rc21 states it (CC
//! 2.6.1.8 step 8: ways (a) to (d), Waiting on what is not held, half-open
//! coverage) and the end rule of step 4 (`valid_until_not_after_asserted_at`),
//! with `location_proof` authored by its subject alone.
//!
//! `tests/vectors/edition2/key_of_iss_v2.json` was generated by
//! `gen_key_of_iss_v2.py` beside it, with its own CBOR encoder over
//! dilithium-py and pyca/cryptography, sharing no code with verify. Each case
//! states its directory: key records, admitted occurrences, evictions, the
//! bundle in force's seats, and a pending bundle. `key_of_iss_v1.json` stays
//! byte-identical and is still replayed by `edition2_key_of_iss_vectors.rs`.
#![cfg(feature = "pqc")]

use ciris_crypto::composite::CompositeSigningKey;
use ciris_verify_core::edition2::family::{
    verify_row_in_family, FamilyVerdict, VendoredFamilyModel,
};
use ciris_verify_core::edition2::keys::KeyRecordDirectory;
use ciris_verify_core::edition2::{
    thumbprint, verify_row_statement, Digest32, MissingKey, Verdict,
};
use serde_json::Value as J;

const FILE: &str = include_str!("vectors/edition2/key_of_iss_v2.json");

fn key(n: u8) -> CompositeSigningKey {
    CompositeSigningKey::from_seeds(&[n; 32], &[n.wrapping_add(100); 32])
}

fn hx(v: &J) -> Vec<u8> {
    hex::decode(v.as_str().unwrap()).unwrap()
}

fn directory(c: &J) -> KeyRecordDirectory {
    let mut d = KeyRecordDirectory::new();
    for r in c["records_hex"].as_array().unwrap() {
        d.insert(hx(r)).expect("a key record");
    }
    for o in c["occurrences_hex"].as_array().unwrap() {
        d.insert_occurrence(hx(o)).expect("an occurrence");
    }
    for e in c["evictions_hex"].as_array().unwrap() {
        d.insert_occurrence_revocation(hx(e));
    }
    let seats: Vec<_> = c["seats"]
        .as_array()
        .unwrap()
        .iter()
        .map(|p| {
            let n = |i: usize| u8::try_from(p[i].as_u64().unwrap()).unwrap();
            (
                thumbprint(key(n(0)).public_key()),
                key(n(1)).public_key().clone(),
            )
        })
        .collect();
    if !seats.is_empty() {
        d.hold_bundle_in_force(seats);
    }
    if let Some(b) = c.get("pending_bundle_hex") {
        let b: Digest32 = hx(b).try_into().unwrap();
        d.await_bundle_in_force(b);
    }
    d
}

fn waiting(m: &[MissingKey]) -> String {
    match m.first() {
        Some(MissingKey::Kid(_)) => "waiting:kid",
        Some(MissingKey::Record(_)) => "waiting:record",
        Some(MissingKey::Voice { .. }) => "waiting:voice",
        Some(MissingKey::Bundle(_)) => "waiting:bundle",
        Some(MissingKey::CoveringRecord { .. }) => "waiting:covering",
        _ => "waiting:other",
    }
    .into()
}

fn snake(debug: &str) -> String {
    let name = debug.split(['(', ' ', '{']).next().unwrap_or(debug);
    let mut out = String::new();
    for (i, ch) in name.chars().enumerate() {
        if ch.is_uppercase() {
            if i > 0 {
                out.push('_');
            }
            out.extend(ch.to_lowercase());
        } else {
            out.push(ch);
        }
    }
    out
}

fn label_statement(v: &Verdict) -> String {
    match v {
        Verdict::Valid(_) => "valid".into(),
        Verdict::Waiting { missing } => waiting(missing),
        Verdict::Invalid(i) => format!(
            "invalid:{}",
            i.token()
                .map_or_else(|| snake(&format!("{i:?}")), str::to_owned)
        ),
    }
}

fn label_family(v: &FamilyVerdict) -> String {
    match v {
        FamilyVerdict::Valid { .. } => "valid".into(),
        FamilyVerdict::Waiting(m) => waiting(m),
        FamilyVerdict::Invalid(i) => format!(
            "invalid:{}",
            i.token()
                .map_or_else(|| snake(&format!("{i:?}")), str::to_owned)
        ),
        FamilyVerdict::FamilyInvalid(f) => format!("family:{}", snake(&format!("{f:?}"))),
    }
}

#[test]
fn every_case_gives_its_outcome() {
    let f: J = serde_json::from_str(FILE).unwrap();
    let cases = f["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 27);
    let mut bad = Vec::new();
    for c in cases {
        let d = directory(c);
        let st = hx(&c["statement_hex"]);
        let got = match c["level"].as_str().unwrap() {
            "family" => label_family(&verify_row_in_family(&st, &d, &VendoredFamilyModel)),
            _ => label_statement(&verify_row_statement(&st, &d)),
        };
        let want = c["expect"].as_str().unwrap();
        if got != want {
            bad.push(format!(
                "{}: want {want}, got {got}",
                c["id"].as_str().unwrap()
            ));
        }
    }
    assert!(bad.is_empty(), "\n{}", bad.join("\n"));
}
